{"cmd":"python - <<'PY'
import json, csv
from pathlib import Path

input_path = Path('/root/trivy_report.json')
output_path = Path('/root/security_audit.csv')

with input_path.open('r', encoding='utf-8') as f:
    data = json.load(f)


def extract_cvss_score(vuln):
    cvss = vuln.get('CVSS', {}) or {}
    # Prefer v3 scores from NVD, then GHSA, then RedHat
    for source in ['nvd', 'ghsa', 'redhat']:
        if source in cvss:
            v3 = cvss[source].get('V3Score')
            if v3 is not None:
                return v3
    # Fallback to NVD v2 if no v3 scores found
    if 'nvd' in cvss:
        v2 = cvss['nvd'].get('V2Score')
        if v2 is not None:
            return v2
    return 'N/A'


def extract_url(vuln):
    primary = vuln.get('PrimaryURL')
    if primary:
        return primary
    refs = vuln.get('References') or []
    if refs:
        return refs[0]
    return 'N/A'


def extract_title(vuln):
    title = vuln.get('Title')
    if title:
        return title
    desc = vuln.get('Description')
    if desc:
        return desc
    return 'N/A'

records = []

for result in data.get('Results', []):
    for vuln in result.get('Vulnerabilities', []) or []:
        severity = vuln.get('Severity')
        if severity not in {'HIGH', 'CRITICAL'}:
            continue
        record = {
            'Package': vuln.get('PkgName') or 'N/A',
            'Version': vuln.get('InstalledVersion') or 'N/A',
            'CVE_ID': vuln.get('VulnerabilityID') or 'N/A',
            'Severity': severity or 'N/A',
            'CVSS_Score': extract_cvss_score(vuln),
            'Fixed_Version': vuln.get('FixedVersion') or 'N/A',
            'Title': extract_title(vuln),
            'Url': extract_url(vuln),
        }
        records.append(record)

headers = ['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score', 'Fixed_Version', 'Title', 'Url']

with output_path.open('w', newline='', encoding='utf-8') as f:
    writer = csv.DictWriter(f, fieldnames=headers)
    writer.writeheader()
    writer.writerows(records)

print(f"Wrote {len(records)} records to {output_path}")
PY"}
